"use client";

import { useState, type ReactNode } from "react";

import { IconCheck } from "@rhs-ui/icons";
import { Avatar, AvatarFallback, initialsOf } from "@rhs-ui/primitives/avatar";
import { Badge } from "@rhs-ui/primitives/badge";
import { Button } from "@rhs-ui/primitives/button";
import { Kbd } from "@rhs-ui/primitives/kbd";
import { RecordNavigator } from "@rhs-ui/primitives/record-navigator";

interface Submission {
  id: string;
  name: string;
  email: string;
  plan: string;
  subject: string;
  message: string;
  received: string;
}

const SUBMISSIONS: readonly Submission[] = [
  { id: "SUB-2039", name: "Marit de Wit", email: "marit@kestrel.example", plan: "Studio", subject: "The February invoice shows the wrong VAT number", message: "Our invoice lists NL8142 but our registration ends in 9306. Could you reissue it before our accountant closes the quarter on Friday?", received: "Mon 09:12" },
  { id: "SUB-2040", name: "Tomás Herrera", email: "tomas@northwind.example", plan: "Team", subject: "CSV export skips archived projects", message: "Since the 4.2 update the export only includes active projects. We rely on the archive column for our yearly audit. Is this intentional, and is there a flag to bring them back?", received: "Mon 10:40" },
  { id: "SUB-2041", name: "Aiko Tanaka", email: "aiko@halcyon.example", plan: "Business", subject: "Can we add a second billing contact?", message: "Finance would like invoices to reach both our controller and the shared accounts mailbox. Right now the billing screen only accepts a single address.", received: "Mon 11:05" },
  { id: "SUB-2042", name: "Josef Brandt", email: "josef@brandt-logistik.example", plan: "Team", subject: "Single sign-on loops back to the sign-in page", message: "After the identity provider confirms the login we land on the sign-in screen again. It started on Thursday and only affects people with a plus sign in their address.", received: "Mon 13:48" },
  { id: "SUB-2043", name: "Lena Fischer", email: "lena@fischer-studio.example", plan: "Studio", subject: "Request: dark mode for the mobile app", message: "I review comps on the train and the white screen is painful after dark. Even a simple follow-the-system option would make a big difference to me.", received: "Mon 15:20" },
  { id: "SUB-2044", name: "Priya Nair", email: "priya@orchard.example", plan: "Business", subject: "Refund for the unused annual seats", message: "We reduced the team from 18 to 12 in June but were billed for 18 seats again at renewal. Please refund the six unused seats from the renewal date.", received: "Tue 08:31" },
  { id: "SUB-2045", name: "Oskar Lindqvist", email: "oskar@lindqvist.example", plan: "Team", subject: "Webhook retries arrive out of order", message: "When our endpoint is down for a minute the queued events come back in a different order than they were sent. Is there a sequence number we should be using?", received: "Tue 09:57" },
  { id: "SUB-2046", name: "Camille Laurent", email: "camille@atelier-laurent.example", plan: "Studio", subject: "Cancel my trial before it renews", message: "I have not had time to try it properly this month. Please cancel the trial so I am not charged, and keep my projects for when I return.", received: "Tue 11:14" },
  { id: "SUB-2047", name: "Daniel Okafor", email: "daniel@okafor-labs.example", plan: "Business", subject: "Where can I find the API rate limits?", message: "Our integration was throttled twice yesterday. I could not find the limits in the documentation, only a vague mention of fair use. Can you share the numbers?", received: "Tue 14:02" },
  { id: "SUB-2048", name: "Sofia Marin", email: "sofia@marin-partners.example", plan: "Team", subject: "Shared dashboards show yesterday's numbers", message: "The dashboard I shared with the board refreshes for me but shows the previous day for everyone with a view-only link. Forcing a refresh does not help them.", received: "Wed 08:49" },
  { id: "SUB-2049", name: "Henrik Vos", email: "henrik@vos-bouw.example", plan: "Studio", subject: "Upgrade from Studio to Team mid-cycle", message: "We would like to move to Team today. Will the unused part of our current month be credited, or do we wait until the next billing date?", received: "Wed 10:26" },
  { id: "SUB-2050", name: "Yara Haddad", email: "yara@haddad-group.example", plan: "Business", subject: "Accessibility statement for procurement", message: "Our procurement team needs a current accessibility statement and conformance report before we can sign. A PDF is fine if one exists.", received: "Wed 12:03" },
];

const FALLBACK: Submission = { id: "SUB-0000", name: "Unknown", email: "none@example.com", plan: "Studio", subject: "", message: "", received: "" };

function Example({ caption, children }: { caption: ReactNode; children: ReactNode }): React.JSX.Element {
  return (
    <div className="grid min-w-0 grid-cols-[minmax(0,1fr)] content-start justify-items-start gap-3">
      <p className="text-xs text-muted-foreground">{caption}</p>
      {children}
    </div>
  );
}

// The rows below only show how the control looks; they own no records.
function noop() {}

function ReviewQueue(): React.JSX.Element {
  const [index, setIndex] = useState(2);
  const [reviewed, setReviewed] = useState<ReadonlySet<string>>(() => new Set(["SUB-2039", "SUB-2040"]));
  const item = SUBMISSIONS[index] ?? SUBMISSIONS[0] ?? FALLBACK;
  const done = reviewed.has(item.id);
  const last = SUBMISSIONS.length - 1;

  return (
    <section aria-label="Support submissions" className="w-full overflow-hidden rounded-xl border border-border bg-card text-card-foreground shadow-xs">
      <header className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2 border-b border-border px-4 py-3">
        <RecordNavigator
          label="submission"
          index={index}
          total={SUBMISSIONS.length}
          onPrevious={() => setIndex((value) => Math.max(0, value - 1))}
          onNext={() => setIndex((value) => Math.min(last, value + 1))}
        />
        <p className="text-xs text-muted-foreground tabular-nums">{reviewed.size} of {SUBMISSIONS.length} reviewed</p>
      </header>

      <article className="grid min-h-64 grid-cols-[minmax(0,1fr)] content-between gap-6 p-5" aria-labelledby="queue-subject">
        <div className="space-y-4">
          <div className="flex items-start gap-3">
            <Avatar>
              <AvatarFallback>{initialsOf(item.name)}</AvatarFallback>
            </Avatar>
            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-medium">{item.name}</p>
              <p className="truncate text-xs text-muted-foreground">
                {item.email} · {item.received}
              </p>
            </div>
            <Badge variant="outline" className="shrink-0">
              {item.plan}
            </Badge>
          </div>
          <div className="space-y-1.5">
            <h3 id="queue-subject" className="text-base font-semibold tracking-[-0.02em] text-balance">
              {item.subject}
            </h3>
            <p className="text-sm leading-relaxed text-muted-foreground">{item.message}</p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Button
            type="button"
            size="sm"
            variant={done ? "secondary" : "default"}
            onClick={() => {
              setReviewed((previous) => new Set(previous).add(item.id));
              setIndex((value) => Math.min(last, value + 1));
            }}
          >
            <IconCheck /> {done ? "Reviewed" : "Mark reviewed and next"}
          </Button>
          <Button type="button" size="sm" variant="outline" onClick={() => setIndex((value) => Math.min(last, value + 1))}>
            Skip
          </Button>
          <span className="ml-auto flex items-center gap-1.5 text-xs text-muted-foreground max-sm:hidden">
            <Kbd>K</Kbd> previous <Kbd>J</Kbd> next
          </span>
        </div>
      </article>
    </section>
  );
}

export default function Demo(): React.JSX.Element {
  return (
    <div className="grid w-full max-w-3xl gap-x-12 gap-y-9 [grid-template-columns:repeat(auto-fit,minmax(min(100%,19rem),1fr))]">
      <div className="min-w-0 [grid-column:1/-1]">
        <Example caption="Step through the queue with the buttons or the J and K keys. The position text is announced after each step.">
          <ReviewQueue />
        </Example>
      </div>

      <Example caption="First record: Previous is dimmed, and its tooltip says why">
        <RecordNavigator label="submission" index={0} total={40} onPrevious={noop} onNext={noop} bindKeys={false} />
      </Example>

      <Example caption="Total still unknown while the list loads">
        <RecordNavigator label="search result" index={2} total={null} onPrevious={noop} onNext={noop} bindKeys={false} />
      </Example>

      <Example caption="With loop, both buttons stay on at the ends so the queue can wrap">
        <RecordNavigator label="submission" index={39} total={40} loop onPrevious={noop} onNext={noop} bindKeys={false} />
      </Example>

      <Example caption="Ghost and small, for a toolbar that has its own surface">
        <RecordNavigator label="row" variant="ghost" size="sm" index={11} total={1284} onPrevious={noop} onNext={noop} bindKeys={false} />
      </Example>
    </div>
  );
}
